#!/usr/bin/env bash
set -euo pipefail
cd /home/frappe/frappe-bench
# exec returns None. Do not use runpy.run_path directly: bench prints its returned
# namespace, which would include API credentials generated by the bootstrap.
bench --site frontend execute exec --args '["exec(open(\"/tmp/ledgerly_bootstrap.py\").read(), {\"__name__\": \"__main__\"})"]'
